// Types mirror the Go JSON contract served by `intropy int run`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  values: Record<string, unknown>
}

export interface FileDoc {
  name: string
  content: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  daprComponents?: string[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
}

async function getJSON<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    throw new Error(message)
  }
  return (await res.json()) as T
}

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  health: () => getJSON<Health>('/api/health'),
}

import type { Integration } from '../api'

interface Props {
  integrations: Integration[] | null
  selected: string | null
  onSelect: (path: string) => void
  collapsed: boolean
  onToggle: () => void
}

export function Sidebar({
  integrations,
  selected,
  onSelect,
  collapsed,
  onToggle,
}: Props) {
  return (
    <aside className={'sidebar' + (collapsed ? ' collapsed' : '')}>
      <div className="sidebar-header">
        {!collapsed && (
          <span className="sidebar-title">
            Integrations
            {integrations && <span className="count">{integrations.length}</span>}
          </span>
        )}
        <button
          className="collapse-btn"
          onClick={onToggle}
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          aria-expanded={!collapsed}
          title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? '»' : '«'}
        </button>
      </div>

      {!collapsed && integrations === null && (
        <p className="muted pad">Loading…</p>
      )}

      {!collapsed && integrations?.length === 0 && (
        <p className="muted pad">No scaffolded integrations found.</p>
      )}

      <ul className="int-list">
        {integrations?.map((it) => {
          const name = integrationName(it)
          const active = it.path === selected
          return (
            <li key={it.path}>
              <button
                className={'int-item' + (active ? ' active' : '')}
                onClick={() => onSelect(it.path)}
                title={collapsed ? `${name} — ${it.path}` : undefined}
              >
                {collapsed ? (
                  <span className="int-initial">{initial(name)}</span>
                ) : (
                  <>
                    <span className="int-name">{name}</span>
                    <span className="int-path">{it.path}</span>
                  </>
                )}
              </button>
            </li>
          )
        })}
      </ul>
    </aside>
  )
}

// integrationName prefers the scaffold's human name, then its appId, then the
// directory path as a last resort.
function integrationName(it: Integration): string {
  const values = it.values ?? {}
  return (values.name as string) || (values.appId as string) || it.path
}

function initial(name: string): string {
  return name.trim().charAt(0).toUpperCase() || '?'
}

