1	package dashboard
2	
3	import (
4		"encoding/json"
5		"net/http"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10	
11		"github.com/integrio-intropy/intropy-cli/internal/template"
12	)
13	
14	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
15	// the detail endpoint returns, so a huge file cannot bloat a response.
16	const maxDocBytes = 128 * 1024
17	
18	// apiServer holds the request-independent state for the JSON API.
19	type apiServer struct {
20		root    string
21		version string
22	}
23	
24	// fileDoc is a text document surfaced in an integration's detail view.
25	type fileDoc struct {
26		Name    string `json:"name"`
27		Content string `json:"content"`
28	}
29	
30	// integrationSummary is a scaffold entry plus the coordinates the sidebar
31	// tree groups by: Name is the directory that carries the .intropy record and
32	// System is that directory's parent. System is empty when the integration
33	// sits directly under the workspace root.
34	type integrationSummary struct {
35		template.ScaffoldEntry
36		Name   string `json:"name"`
37		System string `json:"system,omitempty"`
38	}
39	
40	// integrationDetail is a single integration plus best-effort, on-disk
41	// enrichment. Every enrichment field is optional and absent when the
42	// corresponding file or directory does not exist.
43	type integrationDetail struct {
44		integrationSummary
45		Agents         *fileDoc `json:"agents,omitempty"`
46		Readme         *fileDoc `json:"readme,omitempty"`
47		DaprComponents []string `json:"daprComponents,omitempty"`
48		PipelineSteps  []string `json:"pipelineSteps,omitempty"`
49	}
50	
51	// newHandler wires the API routes and the SPA static handler onto a mux.
52	func newHandler(root, version string) (http.Handler, error) {
53		api := &apiServer{root: root, version: version}
54		static, err := staticHandler()
55		if err != nil {
56			return nil, err
57		}
58	
59		mux := http.NewServeMux()
60		mux.HandleFunc("GET /api/health", api.health)
61		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
62		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
63		mux.Handle("/", static)
64		return mux, nil
65	}
66	
67	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
68		writeJSON(w, http.StatusOK, map[string]string{
69			"status":  "ok",
70			"version": s.version,
71		})
72	}
73	
74	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
75	// the same order — with the derived name/system fields added on top. The
76	// response is always an array (never null) even when empty.
77	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
78		entries, _ := template.ListScaffolds(s.root)
79		summaries := make([]integrationSummary, 0, len(entries))
80		for _, e := range entries {
81			summaries = append(summaries, s.summarize(e))
82		}
83		writeJSON(w, http.StatusOK, summaries)
84	}
85	
86	// summarize derives an entry's tree coordinates from its path. The workspace
87	// root itself never counts as a system, and an integration scaffolded at the
88	// root has no system at all.
89	func (s *apiServer) summarize(e template.ScaffoldEntry) integrationSummary {
90		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
91		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
92		if parent := filepath.Dir(path); path != root && parent != root {
93			sum.System = filepath.Base(parent)
94		}
95		return sum
96	}
97	
98	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
99		want := strings.Trim(r.PathValue("path"), "/")
100		entries, _ := template.ListScaffolds(s.root)
101		for _, e := range entries {
102			if filepath.ToSlash(e.Path) == want {
103				writeJSON(w, http.StatusOK, s.enrich(e))
104				return
105			}
106		}
107		writeError(w, http.StatusNotFound, "integration not found: "+want)
108	}
109	
110	// enrich reads optional on-disk context for an integration. The entry's Path
111	// is already usable from the process working directory (see ListScaffolds), so
112	// it doubles as the project directory.
113	func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
114		dir := e.Path
115		return integrationDetail{
116			integrationSummary: s.summarize(e),
117			Agents:             readDoc(dir, "AGENTS.md"),
118			Readme:             readDoc(dir, "README.md"),
119			DaprComponents:     listNames(filepath.Join(dir, "local", "dapr-components")),
120			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
121		}
122	}
123	
124	// readDoc returns the named text file's (possibly truncated) contents, or nil
125	// if it is absent or unreadable.
126	func readDoc(dir, name string) *fileDoc {
127		data, err := os.ReadFile(filepath.Join(dir, name))
128		if err != nil {
129			return nil
130		}
131		if len(data) > maxDocBytes {
132			data = data[:maxDocBytes]
133		}
134		return &fileDoc{Name: name, Content: string(data)}
135	}
136	
137	// listNames returns the sorted base names of the files directly under dir, or
138	// nil if dir is absent or unreadable.
139	func listNames(dir string) []string {
140		ents, err := os.ReadDir(dir)
141		if err != nil {
142			return nil
143		}
144		var names []string
145		for _, ent := range ents {
146			if !ent.IsDir() {
147				names = append(names, ent.Name())
148			}
149		}
150		sort.Strings(names)
151		return names
152	}
153	
154	func writeJSON(w http.ResponseWriter, status int, v any) {
155		w.Header().Set("Content-Type", "application/json; charset=utf-8")
156		w.WriteHeader(status)
157		enc := json.NewEncoder(w)
158		enc.SetIndent("", "  ")
159		_ = enc.Encode(v)
160	}
161	
162	func writeError(w http.ResponseWriter, status int, msg string) {
163		writeJSON(w, status, map[string]string{"error": msg})
164	}

