:root {
  --bg: #f7f8fa;
  --surface: #ffffff;
  --surface-2: #f1f3f5;
  --border: #e3e6ea;
  --text: #1a1d21;
  --text-muted: #6b7280;
  --accent: #0d9488;
  --accent-soft: #0d948814;
  --danger: #b42318;
  --danger-soft: #b423180f;
  --radius: 10px;
  --sidebar-w: 300px;
  --sidebar-rail-w: 56px;
  --topbar-h: 56px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e1116;
    --surface: #151a21;
    --surface-2: #1c222b;
    --border: #262d38;
    --text: #e6e9ee;
    --text-muted: #9aa4b2;
    --accent: #2dd4bf;
    --accent-soft: #2dd4bf1a;
    --danger: #ff6b6b;
    --danger-soft: #ff6b6b14;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Top bar */
.topbar {
  height: var(--topbar-h);
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.brand-mark {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: var(--accent);
  align-self: center;
}

.brand-name {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.brand-sub {
  color: var(--text-muted);
}

.version {
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
  font-size: 12px;
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
}

/* Layout */
.layout {
  flex: 1 1 auto;
  display: flex;
  min-height: 0;
}

/* Sidebar */
.sidebar {
  width: var(--sidebar-w);
  flex: 0 0 auto;
  border-right: 1px solid var(--border);
  background: var(--surface);
  overflow-y: auto;
  overflow-x: hidden;
  transition: width 0.16s ease;
}

.sidebar.collapsed {
  width: var(--sidebar-rail-w);
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 14px 12px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.sidebar.collapsed .sidebar-header {
  justify-content: center;
}

.sidebar-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 1 1 auto;
  min-width: 0;
}

.collapse-btn {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
}

.collapse-btn:hover {
  background: var(--surface-2);
  color: var(--text);
}

.count {
  font-variant-numeric: tabular-nums;
  background: var(--surface-2);
  border-radius: 999px;
  padding: 1px 8px;
}

.int-list {
  list-style: none;
  margin: 0;
  padding: 4px 8px 16px;
}

.sidebar.collapsed .int-list {
  padding: 4px 8px 16px;
}

.int-item {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
  padding: 9px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
}

.sidebar.collapsed .int-item {
  align-items: center;
  padding: 6px;
}

.int-initial {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: var(--surface-2);
  font-weight: 600;
}

.sidebar.collapsed .int-item.active .int-initial {
  background: var(--accent);
  color: #fff;
}

.int-item:hover {
  background: var(--surface-2);
}

.int-item.active {
  background: var(--accent-soft);
  border-color: var(--accent);
}

.int-name {
  font-weight: 600;
}

.int-path {
  font-size: 12px;
  color: var(--text-muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* Content */
.content {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 28px 32px 48px;
}

.empty {
  color: var(--text-muted);
  margin-top: 12px;
}

.banner {
  padding: 10px 14px;
  border-radius: 8px;
  margin-bottom: 20px;
}

.banner.error {
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid var(--danger);
}

.detail {
  max-width: 860px;
