:root {
  --bg: #f7f8fa;
  --surface: #ffffff;
  --surface-2: #f1f3f5;
  --border: #e3e6ea;
  --text: #1a1d21;
  --text-muted: #6b7280;
  --accent: #0d9488;
  --accent-soft: #0d948814;
  --danger: #b42318;
  --danger-soft: #b423180f;
  --radius: 10px;
  --sidebar-w: 300px;
  --sidebar-rail-w: 56px;
  --topbar-h: 56px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e1116;
    --surface: #151a21;
    --surface-2: #1c222b;
    --border: #262d38;
    --text: #e6e9ee;
    --text-muted: #9aa4b2;
    --accent: #2dd4bf;
    --accent-soft: #2dd4bf1a;
    --danger: #ff6b6b;
    --danger-soft: #ff6b6b14;
  }
}

* {
  box-sizing: border-box;
}

/* Material Symbols SVGs: sized like text glyphs, tinted via currentColor */
.icon {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  fill: currentColor;
  vertical-align: -3px;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Top bar */
.topbar {
  height: var(--topbar-h);
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.brand-mark {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: var(--accent);
  align-self: center;
}

.brand-name {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.brand-sub {
  color: var(--text-muted);
}

.version {
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
  font-size: 12px;
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
}

/* Layout */
.layout {
  flex: 1 1 auto;
  display: flex;
  min-height: 0;
}

/* Sidebar */
.sidebar {
  width: var(--sidebar-w);
  flex: 0 0 auto;
  border-right: 1px solid var(--border);
  background: var(--surface);
  overflow-y: auto;
  overflow-x: hidden;
  transition: width 0.16s ease;
}

.sidebar.collapsed {
  width: var(--sidebar-rail-w);
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 14px 12px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.sidebar.collapsed .sidebar-header {
  justify-content: center;
}

.sidebar-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 1 1 auto;
  min-width: 0;
}

.collapse-btn {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
}

.collapse-btn:hover {
  background: var(--surface-2);
  color: var(--text);
}

.count {
  font-variant-numeric: tabular-nums;
  background: var(--surface-2);
  border-radius: 999px;
  padding: 1px 8px;
}

/* Sidebar tree: systems with their integrations nested underneath */
.tree {
  padding: 0 8px 16px;
}

.sys-group + .sys-group {
  margin-top: 2px;
}

.sys-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  text-align: left;
}

.sys-header:hover {
  background: var(--surface-2);
}

.caret {
  width: 16px;
  height: 16px;
  color: var(--text-muted);
  transition: transform 0.12s ease;
}

.caret.open {
  transform: rotate(90deg);
}

.sys-icon {
  color: var(--text-muted);
}

.sys-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.int-list {
  list-style: none;
  margin: 0;
  padding: 4px 8px 16px;
}

.tree .int-list {
  padding: 2px 0 6px;
}

.tree .int-list.nested {
  padding-left: 18px;
}

.sidebar.collapsed .int-list {
  padding: 4px 8px 16px;
}

.int-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  padding: 9px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
}

.int-icon {
  width: 16px;
  height: 16px;
  color: var(--text-muted);
}

.int-item.active .int-icon {
  color: var(--accent);
}

.int-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.sidebar.collapsed .int-item {
  align-items: center;
  justify-content: center;
  padding: 6px;
}

.int-initial {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: var(--surface-2);
  font-weight: 600;
}

.sidebar.collapsed .int-item.active .int-initial {
  background: var(--accent);
  color: #fff;
}

.int-item:hover {
  background: var(--surface-2);
}

.int-item.active {
  background: var(--accent-soft);
  border-color: var(--accent);
}

.int-name {
  font-weight: 600;
}

.int-name,
.int-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.int-path {
  font-size: 12px;
  color: var(--text-muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* Content */
.content {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 28px 32px 48px;
}

.empty {
  color: var(--text-muted);
  margin-top: 12px;
}

.banner {
  padding: 10px 14px;
  border-radius: 8px;
  margin-bottom: 20px;
}

.banner.error {
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid var(--danger);
}

.detail {
  max-width: 860px;
}

.detail-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin: 0 0 20px;
}

.meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 14px;
  background: var(--surface);
}

.meta-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.meta-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  word-break: break-all;
}

.section {
  margin-top: 30px;
}

.section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin: 0 0 12px;
}

.section-title .icon {
  width: 16px;
  height: 16px;
}

.kv {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.kv th,
.kv td {
  text-align: left;
  padding: 9px 14px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.kv tr:last-child th,
.kv tr:last-child td {
  border-bottom: none;
}

.kv th {
  width: 30%;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--surface-2);
}

.kv td {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  background: var(--surface);
}

.steps {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.chips {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
}

.doc {
  margin: 0;
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  line-height: 1.6;
  max-height: 480px;
  overflow-y: auto;
}

.muted {
  color: var(--text-muted);
}

.pad {
  padding: 4px 16px;
}

